/**
 * Autogenerated by Postman CLI (postman mock generate)
 * Manually fixed during dogfooding — now genuinely stateful, scoped by an
 * optional x-mock-session header (falls back to "default") so CI runs, the
 * Monitor, and manual/demo use don't share or corrupt each other's orders.
 */
const http = require('http');
const PORT = process.env.PORT || 5003;

const SEED_ORDERS = [
  {
    id: 'o1',
    userId: 'demo-user',
    items: [
      { productId: 'p1', name: 'Wireless Noise-Cancelling Headphones', price: 149.99, quantity: 1 },
      { productId: 'p4', name: 'Memory Foam Throw Pillow', price: 24.99, quantity: 1 },
    ],
    total: 174.98,
    status: 'confirmed',
    createdAt: '2026-09-22T21:17:21.304Z',
  },
  {
    id: 'o2',
    userId: 'postman-cli-order-test',
    items: [
      { productId: 'p1', name: 'Wireless Noise-Cancelling Headphones', price: 149.99, quantity: 2 },
      { productId: 'p3', name: 'Ceramic Pour-Over Coffee Set', price: 39.50, quantity: 1 },
    ],
    total: 339.48,
    status: 'shipped',
    createdAt: '2026-09-22T22:49:02.600Z',
  },
  {
    id: 'o3',
    userId: 'postman-cli-test-user',
    items: [{ productId: 'p1', name: 'Wireless Noise-Cancelling Headphones', price: 149.99, quantity: 5 }],
    total: 749.95,
    status: 'delivered',
    createdAt: '2026-09-22T22:51:00.443Z',
  },
];

// mockSession -> orders array, seeded with a fresh copy of SEED_ORDERS on
// first use per session so manual/demo use still looks populated.
const sessions = new Map();

function getOrders(req) {
  const mockSession = req.headers['x-mock-session'] || 'default';
  if (!sessions.has(mockSession)) {
    sessions.set(mockSession, JSON.parse(JSON.stringify(SEED_ORDERS)));
  }
  return sessions.get(mockSession);
}

function readBody(req, cb) {
  let data = '';
  req.on('data', (chunk) => (data += chunk));
  req.on('end', () => {
    try {
      cb(data ? JSON.parse(data) : {});
    } catch (e) {
      cb({});
    }
  });
}

// Returns the body's unexpected top-level keys (those not in allowedKeys),
// or null if there are none / the body isn't a plain object.
function unexpectedFields(body, allowedKeys) {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) return null;
  const extra = Object.keys(body).filter((key) => !allowedKeys.includes(key));
  return extra.length > 0 ? extra : null;
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url || '', 'http://localhost');
  const pathname = url.pathname;

  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,OPTIONS');
  res.setHeader(
    'Access-Control-Allow-Headers',
    'Content-Type,x-user-id,x-mock-response-code,x-mock-scenario,x-api-key,x-mock-session'
  );
  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    return res.end();
  }

  const requestedStatusCode = req.headers['x-mock-response-code'];

  // @endpoint GET /health
  if (req.method === 'GET' && pathname === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({ status: 'ok', service: 'order-service' }));
  }

  // @endpoint POST /api/orders
  if (req.method === 'POST' && pathname === '/api/orders') {
    return readBody(req, (body) => {
      const extra = unexpectedFields(body, ['userId', 'items', 'total']);
      if (extra) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        return res.end(
          JSON.stringify({ error: `Unexpected field(s) in request body: ${extra.join(', ')}` })
        );
      }
      if (
        requestedStatusCode === '400' ||
        typeof body.userId !== 'string' ||
        !body.userId.trim() ||
        !Array.isArray(body.items) ||
        body.items.length === 0
      ) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        return res.end(
          JSON.stringify({ error: 'userId is required and items must be a non-empty array' })
        );
      }
      const orders = getOrders(req);
      const order = {
        id: 'o' + (orders.length + 1),
        userId: body.userId,
        items: body.items,
        total: typeof body.total === 'number' ? body.total : 0,
        status: 'confirmed',
        createdAt: new Date().toISOString(),
      };
      orders.push(order);
      res.writeHead(201, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify(order));
    });
  }

  // @endpoint GET /api/orders
  if (req.method === 'GET' && pathname === '/api/orders') {
    const userIdFilter = url.searchParams.get('userId');
    let orders = getOrders(req);
    if (userIdFilter) orders = orders.filter((o) => o.userId === userIdFilter);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify([...orders].reverse()));
  }

  const idMatch = pathname.match(/^\/api\/orders\/(.+)$/);

  // @endpoint GET /api/orders/{id}
  if (req.method === 'GET' && idMatch) {
    if (requestedStatusCode === '404') {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ error: 'Order not found' }));
    }
    const orderId = decodeURIComponent(idMatch[1]);
    const order = getOrders(req).find((o) => o.id === orderId);
    if (!order) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ error: 'Order not found' }));
    }
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify(order));
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(PORT, () => {
  console.log(`Order Service Mock listening on http://localhost:${PORT}`);
});
